shellCommands.command:
set -e; for endpoint in / /blog /blog/1 /missing /api/posts /api/posts/1; do curl -s -o /dev/null -w "$endpoint %{http_code}
" "http://localhost:3199$endpoint"; done; curl -s -o /dev/null -w 'POST /api/posts %{http_code}
' -X POST -H 'content-type: application/json' -d '{"title":"A","content":"B"}' http://localhost:3199/api/posts; curl -s -o /dev/null -w 'PUT /api/posts/1 %{http_code}
' -X PUT -H 'content-type: application/json' -d '{"title":"A"}' http://localhost:3199/api/posts/1; curl -s -o /dev/null -w 'DELETE /api/posts/1 %{http_code}
' -X DELETE http://localhost:3199/api/posts/1; curl -s -o /dev/null -w 'PATCH /api/posts %{http_code}
' -X PATCH http://localhost:3199/api/posts
